import{_ as i,o as a,c as t,ai as n}from"./chunks/framework.Ba-VnP44.js";const g=JSON.parse('{"title":"离线优先的终端应用设计","description":"","frontmatter":{},"headers":[],"relativePath":"apps/terminal/offline-first.md","filePath":"apps/terminal/offline-first.md"}'),l={name:"apps/terminal/offline-first.md"};function e(p,s,r,d,h,o){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="离线优先的终端应用设计" tabindex="-1">离线优先的终端应用设计 <a class="header-anchor" href="#离线优先的终端应用设计" aria-label="Permalink to “离线优先的终端应用设计”">​</a></h1><h2 id="背景与问题" tabindex="-1">背景与问题 <a class="header-anchor" href="#背景与问题" aria-label="Permalink to “背景与问题”">​</a></h2><p>仓库、车间、野外巡检这类场景，网络断续是常态而不是异常。多数应用的默认写法是「在线为主、缓存兜底」：数据从服务端拉下来放内存，断网时界面转圈，恢复后整页刷新。这种写法在终端场景会出三类事故：</p><ul><li><strong>断网期间用户动作丢失</strong>：扫了码、点了确认，提示「网络异常」，人一急重复操作，恢复后数据又乱。</li><li><strong>恢复后整包覆盖</strong>：重新拉取时把本地改动冲掉，或者把别人的新数据冲掉——同步=覆盖，没有冲突概念。</li><li><strong>回补逻辑临时补</strong>：断网两周的设备上线时一次性灌几万条，超时、内存爆、顺序错乱。</li></ul><p>离线优先（offline-first）换个思路：<strong>本地存储是数据的主副本，网络只是同步通道</strong>。界面永远读写本地，同步在后台异步进行，冲突按规则处理。这个思路不是新概念（PWA、RxDB、CRDT 讨论了很多年），落到工程上真正要做的是四件事：本地优先存储、变更队列、冲突策略、重连补偿。</p><h2 id="方案设计" tabindex="-1">方案设计 <a class="header-anchor" href="#方案设计" aria-label="Permalink to “方案设计”">​</a></h2><p><strong>核心模型</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UI（永远读本地，永远写本地）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>本地库（SQLite/Room：业务表 + 变更队列 outbox + 同步游标）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>同步引擎（按游标拉增量、按队列推变更、冲突裁决、记录结果）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>服务端（全量/增量接口 + 冲突裁决 + 操作日志）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>四个设计决定</strong>：</p><ol><li><strong>本地优先存储</strong>：业务数据落 SQLite（关系型、可查询、可事务），所有写操作先在本地事务里完成，UI 立即可见——本地写成功就是「保存成功」，与网络无关。</li><li><strong>变更队列（outbox）</strong>：每次业务写在<strong>同一事务</strong>里生成一条变更记录（表、行、操作类型、前后镜像或增量、opId、时间戳），同步引擎只搬运 outbox，业务代码不直接碰网络。</li><li><strong>冲突策略先定规则</strong>：按数据类型分层——能幂等的用幂等消掉；能字段合并的合并；有业务语义冲突（数量、状态）的抛给人工。<strong>没有万能策略，按表定策略</strong>。</li><li><strong>重连补偿</strong>：上线后按游标增量拉 + 分批推 + 断点续传，禁止全量覆盖和一次性回灌。</li></ol><p><strong>同步协议（示意）</strong>：</p><ul><li>下行：<code>GET /sync/pull?cursor=&amp;limit=</code> 返回变更列表 + 新游标；服务端发的每条变更也带 opId。</li><li>上行：<code>POST /sync/push</code> 提交 outbox 批次，逐条返回 <code>applied / duplicate / conflict / rejected</code>。</li><li>两端都记录对方的 opId，实现<strong>双向去重</strong>——防止「我推上去的变更又被拉回来当成对方的新变更」。</li></ul><h2 id="关键实现" tabindex="-1">关键实现 <a class="header-anchor" href="#关键实现" aria-label="Permalink to “关键实现”">​</a></h2><p><strong>1. 本地写 + outbox 同事务</strong></p><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BEGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> task </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> done_qty </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> done_qty </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;T-1001&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  INSERT INTO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> outbox(op_id, table_name, row_id, op, payload, created_at, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;o-20261014-0001&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;task&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;T-1001&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;UPDATE&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          &#39;{&quot;done_qty&quot;: 110}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, strftime(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%s&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;now&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PENDING&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COMMIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>同步引擎只认 <code>status = &#39;PENDING&#39;</code> 的记录，按 <code>created_at</code> 顺序分批（如 50 条）推送；成功置 <code>SYNCED</code>，冲突置 <code>CONFLICT</code> 并带原因。<strong>业务代码永远不直接调同步接口</strong>，保证断网时行为与在线时完全一致。</p><p><strong>2. 变更队列与去重</strong></p><ul><li><code>opId</code> 客户端生成（时间戳 + 设备号 + 序列），全局唯一，服务端唯一索引兜底；</li><li>服务端应用变更时把 <code>opId</code> 写入操作日志，重复推送返回上次结果（幂等）；</li><li>下行变更同样带 opId，客户端发现是自己推过的直接忽略，避免回环。</li></ul><p><strong>3. 冲突解决策略（按数据类型分层）</strong></p><table tabindex="0"><thead><tr><th>数据类型</th><th>策略</th><th>说明</th></tr></thead><tbody><tr><td>追加型（扫码记录、日志）</td><td>天然无冲突</td><td>只做去重，永不覆盖</td></tr><tr><td>计数/数量型</td><td>服务端聚合为准</td><td>本地显示「已回传」与「待回传」分开</td></tr><tr><td>字段独立型（备注、地址）</td><td>字段级合并</td><td>不同字段各写各的，同字段后写让步</td></tr><tr><td>状态机型（任务状态）</td><td>服务端裁决</td><td>非法流转拒绝，返回当前权威状态</td></tr><tr><td>关键业务冲突</td><td>进异常队列人工判</td><td>双方数据都保留，绝不静默丢弃</td></tr></tbody></table><p>实现上可用 <code>version</code> 字段做乐观锁：推变更时带上读到的版本，版本不匹配服务端返回当前值，客户端按上表策略处理（自动改或转人工）。</p><p><strong>4. 重连补偿</strong></p><ul><li>网络恢复事件触发一次 sync，之后按「在线：10s 一次；离线：停止」的节奏调度；</li><li>push 失败指数退避（2s→4s→…→60s 封顶），<strong>永远限制批量大小</strong>，断网三天的设备分几十批慢慢补，每批带断点；</li><li>pull 按游标增量，服务端保留变更日志的窗口（如 7 天）；超出窗口或游标失效时降级为「全量快照 + 本地未同步数据重新排队」；</li><li>冲突记录不阻塞正常同步：<code>CONFLICT</code> 的行停在本地等人处理，其余记录继续流转。</li></ul><p><strong>5. 边界处理</strong></p><ul><li>存储上限：outbox 和本地日志设配额，超限时提示并引导优先回传；</li><li>时间：设备时钟可能不准，排序以服务端接收序 + 单调序列为准，时间戳只作参考；</li><li>测试：用「网络开关 + 时钟偏移 + 批量冲突」三个维度做自动化模拟，同步逻辑必须能离线回归。</li></ul><h2 id="落地效果-示意" tabindex="-1">落地效果（示意） <a class="header-anchor" href="#落地效果-示意" aria-label="Permalink to “落地效果（示意）”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>在线优先（常见问题）</th><th>离线优先（预期，示意）</th></tr></thead><tbody><tr><td>断网作业</td><td>提示失败，人工纸单记录</td><td>照常作业，变更进 outbox</td></tr><tr><td>恢复网络</td><td>整页刷新，可能覆盖本地</td><td>分批补传，按规则裁决冲突</td></tr><tr><td>断网很久后上线</td><td>一次性回灌超时失败</td><td>游标增量 + 断点续传</td></tr><tr><td>重复推送</td><td>产生重复业务数据</td><td>opId 幂等，重复无副作用</td></tr></tbody></table><p>补传成功率、冲突队列积压量是上线后要盯的两个指标，需要按周统计确认策略是否要调整。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>离线优先不是「加个缓存」，是把因果关系反过来：<strong>本地是主、网络是从</strong>。落地动作就四步——业务数据进本地库且本地写即成功，写操作同事务进变更队列，按数据类型预先定好冲突规则（幂等、聚合、合并、人工四选一），恢复后按游标和批次补偿而不是全量覆盖。冲突规则这一步最容易被跳过，也是现场数据出问题后最难补救的一步：先在接口文档里把每张表的冲突策略写清楚，再动手写同步引擎。</p>`,30)])])}const c=i(l,[["render",e]]);export{g as __pageData,c as default};
